import { mkdirSync } from "node:fs";
import { dirname } from "node:path";

import { createClient } from "@libsql/client";
import { drizzle, type LibSQLDatabase } from "drizzle-orm/libsql";
import { migrate } from "drizzle-orm/libsql/migrator";

import * as schema from "@/lib/schema";

/**
 * Database connector (Drizzle ORM + libSQL).
 *
 * `getDb()` returns a lazily-created, shared Drizzle instance backed by a libSQL
 * file database. On first use it runs any pending migrations from `./drizzle`
 * (generated by `npm run db:generate`). The client and the one-time migration
 * promise are cached on `globalThis` so dev HMR reuses them instead of
 * reconnecting/re-migrating on every reload.
 *
 * The database lives at `DATABASE_URL` (defaults to `file:./data/app.db`).
 */

const DATABASE_URL = process.env.DATABASE_URL ?? "file:./data/app.db";

type DB = LibSQLDatabase<typeof schema>;

const globalForDb = globalThis as unknown as {
  __db__?: DB;
  __dbReady__?: Promise<unknown>;
};

function ensureParentDir(url: string): void {
  if (url.startsWith("file:")) {
    mkdirSync(dirname(url.slice("file:".length)), { recursive: true });
  }
}

function init(): void {
  ensureParentDir(DATABASE_URL);
  const client = createClient({ url: DATABASE_URL });
  const db = drizzle(client, { schema });
  globalForDb.__db__ = db;
  globalForDb.__dbReady__ = migrate(db, { migrationsFolder: "./drizzle" });
}

export async function getDb(): Promise<DB> {
  if (!globalForDb.__db__) {
    init();
  }
  await globalForDb.__dbReady__;
  return globalForDb.__db__!;
}
